"""Report configured values and unresolved interpretation; never certify a model."""
from pathlib import Path
import json,datetime
NBC='https://giwmscdnone.gov.np/media/files/NBC_105_2025_Seismic%20Design%20of%20Buildings%20in%20Nepal_lqqvx6a.pdf'
def audit(folder):
 folder=Path(folder);cfg=json.loads((folder/'OpenSees_Complete_Model_Config_V118.json').read_text(encoding='utf-8-sig'))
 rows=[dict(item='Gravity versus seismic mass',value=cfg.get('gravity_factors'),status='REVIEW COMBINATION BASIS',basis='NBC 5.2 / Table 5-1 mass participation is not a universal gravity load combination. AS_CONFIGURED 0.3LL preload must be justified separately from 3.6 design cases.'),dict(item='Elastic wall effective stiffness',value='Production ShellMITC4 uses source gross in-plane stiffness',status='ACTION REQUIRED',basis='NBC Table 3-1: cracked wall EI ULS 0.50, SLS 0.70; uncracked 0.80/0.90. Current slab bending section does not modify wall in-plane membrane bending. Match a justified wall idealization in both ETABS and OpenSees before design comparison.'),dict(item='Conventional slab bending factors',value=[cfg.get('slab_bending_factor'),cfg.get('slab_bending_factor_sls')],status='VERIFY SLAB TYPE AND SOURCE',basis=cfg.get('slab_stiffness_source','No source recorded')+'; NBC Table 3-1 flat-slab factors 0.25/0.50 are not automatically applicable to a conventional beam-supported slab.'),dict(item='RC frame effective EI',value='Beam 0.35/0.70; column 0.70/0.90 (ULS/SLS)',status='IMPLEMENTATION REFERENCE',basis='NBC Table 3-1; geometry and source material E remain project inputs.'),dict(item='Section adequacy',value='Actual reinforcement / capacities required',status='NOT VERIFIED',basis='Equilibrium and modal mass coverage do not establish PMM, shear, stability, anchorage or ductile detailing adequacy.'),dict(item='Drift',value='ULS 0.025; SLS 0.006',status='CODE LIMIT REFERENCE',basis='NBC 5.5.3; ULS elastic displacement amplification Rmu under 5.5.1; ESM kd under 6.5; MRSM force-only scale under 7.5 must not scale drift.'),dict(item='Wall nonlinear calibration',value={'reviewed':cfg.get('nonlinear_parameters_reviewed'),'materials':cfg.get('nonlinear_materials_file'),'FSAM':cfg.get('nonlinear_wall_fsam_tags')},status='REQUIRES PROJECT EVIDENCE',basis='Kolozvari et al. 2023 E-SFI-MVLEM-3D; Lu et al. 2015 layered-shell alternative. Published example parameters are not project calibration.')]
 return dict(created=datetime.datetime.now().astimezone().isoformat(),source=NBC,rows=rows,overall='REVIEW REQUIRED - not a compliance certificate')
def launch(parent,folder):
 import tkinter as tk
 from tkinter import ttk,messagebox
 try:report=audit(folder)
 except Exception as e:messagebox.showerror('Settings audit',str(e),parent=parent);return
 win=tk.Toplevel(parent);win.title('NBC settings - values, sources and unresolved inputs');win.geometry('1150x700');text=tk.Text(win,wrap='word');sy=ttk.Scrollbar(win,command=text.yview);text.configure(yscrollcommand=sy.set);sy.pack(side='right',fill='y');text.pack(fill='both',expand=True)
 text.insert('end',json.dumps(report,indent=2,ensure_ascii=False));text.configure(state='disabled');return win
